// Build a clean video payload from the current Google Sheets row.
// Expected columns: Final_Voiceover, scene_1, scene_2, scene_3, scene_4.
// Optional: video_title
const row = $json;

const required = ['Final_Voiceover','scene_1','scene_2','scene_3','scene_4'];
for (const key of required) {
  if (!row[key] || String(row[key]).trim() === '') {
    throw new Error(`Missing Google Sheets column/value: ${key}`);
  }
}

return [{
  json: {
    video_title: row.video_title || row.Video_Title || row.title || 'AI Generated Short',
    final_voiceover: String(row.Final_Voiceover).trim(),
    scenes: [
      { scene: 1, description: String(row.scene_1).trim() },
      { scene: 2, description: String(row.scene_2).trim() },
      { scene: 3, description: String(row.scene_3).trim() },
      { scene: 4, description: String(row.scene_4).trim() }
    ]
  }
}];

// ============================================================
// BUILD SHORT VIDEO MAKER PAYLOAD
// ============================================================
// Purpose:
// 1. Get the original 4 scenes
// 2. Safely parse the NVIDIA/AI response
// 3. Match AI search terms to the correct scenes
// 4. Validate exactly 4 Pexels terms per scene
// 5. Clean and normalize search terms
// 6. Remove duplicate/poor-quality terms
// 7. Preserve the original scene descriptions
// 8. Disable background music
// 9. Build a clean Short Video Maker payload
// ============================================================


// ============================================================
// 1. GET ORIGINAL SCENE DATA
// ============================================================

const source = $('Prepare 4 Scenes').item.json;

if (!source) {
  throw new Error(
    'Prepare 4 Scenes did not return any data.'
  );
}

if (!Array.isArray(source.scenes)) {
  throw new Error(
    'Prepare 4 Scenes did not provide a valid scenes array.'
  );
}

if (source.scenes.length !== 4) {
  throw new Error(
    `Prepare 4 Scenes must contain exactly 4 scenes. Found ${source.scenes.length}.`
  );
}


// ============================================================
// 2. GET AI RESPONSE
// ============================================================

const raw = $json?.choices?.[0]?.message?.content;

if (raw === undefined || raw === null || raw === '') {
  throw new Error(
    'AI Create Pexels Search Terms returned no content.'
  );
}


// ============================================================
// 3. CONVERT AI RESPONSE TO STRING
// ============================================================

let rawText;

if (typeof raw === 'string') {
  rawText = raw.trim();
} else {
  rawText = JSON.stringify(raw);
}


// ============================================================
// 4. REMOVE MARKDOWN CODE FENCES
// ============================================================
// The AI prompt says not to use Markdown, but this protects
// the workflow if the model accidentally returns ```json ... ```.
// ============================================================

rawText = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();


// ============================================================
// 5. PARSE JSON
// ============================================================

let parsed;

try {
  parsed = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    'AI output was not valid JSON.\n\n' +
    'Raw AI output:\n' +
    rawText
  );
}


// ============================================================
// 6. VALIDATE AI SCENES
// ============================================================

if (!parsed || !Array.isArray(parsed.scenes)) {
  throw new Error(
    'AI output does not contain a valid "scenes" array.'
  );
}

if (parsed.scenes.length !== 4) {
  throw new Error(
    `AI output must contain exactly 4 scenes. Found ${parsed.scenes.length}.`
  );
}


// ============================================================
// 7. SEARCH TERM CLEANER
// ============================================================

function cleanSearchTerm(term) {

  if (typeof term !== 'string') {
    return '';
  }

  return term
    // Remove punctuation
    .replace(/[^\w\s-]/g, ' ')

    // Replace multiple spaces
    .replace(/\s+/g, ' ')

    // Remove leading/trailing whitespace
    .trim()

    // Lowercase for consistent Pexels searching
    .toLowerCase();
}


// ============================================================
// 8. SEARCH TERM VALIDATION
// ============================================================

function isValidSearchTerm(term) {

  if (!term) {
    return false;
  }

  // Must contain 2–6 words
  const wordCount = term.split(/\s+/).length;

  if (wordCount < 2 || wordCount > 6) {
    return false;
  }

  // Avoid extremely generic single concepts
  const genericTerms = new Set([
    'health',
    'wellness',
    'healthy',
    'healthy lifestyle',
    'lifestyle',
    'motivation',
    'happiness',
    'fitness',
    'person',
    'people',
    'life',
    'nature',
    'success',
    'stress',
    'exercise',
    'medicine',
    'medical',
    'body',
    'mind',
    'healthcare'
  ]);

  if (genericTerms.has(term)) {
    return false;
  }

  return true;
}


// ============================================================
// 9. PROCESS EACH SCENE
// ============================================================

const scenes = source.scenes.map((scene, index) => {

  // ----------------------------------------------------------
  // Find corresponding AI scene
  // ----------------------------------------------------------

  const aiScene =
    parsed.scenes.find(
      s => Number(s?.scene) === Number(scene.scene)
    ) ||
    parsed.scenes[index];


  if (!aiScene) {
    throw new Error(
      `Missing AI data for scene ${scene.scene}.`
    );
  }


  // ----------------------------------------------------------
  // Validate searchTerms exists
  // ----------------------------------------------------------

  if (!Array.isArray(aiScene.searchTerms)) {
    throw new Error(
      `Scene ${scene.scene} does not contain a valid searchTerms array.`
    );
  }


  // ----------------------------------------------------------
  // Clean search terms
  // ----------------------------------------------------------

  const cleanedTerms = aiScene.searchTerms
    .map(cleanSearchTerm)
    .filter(Boolean);


  // ----------------------------------------------------------
  // Remove duplicate terms
  // ----------------------------------------------------------

  const uniqueTerms = [
    ...new Set(cleanedTerms)
  ];


  // ----------------------------------------------------------
  // Remove invalid/generic terms
  // ----------------------------------------------------------

  const validTerms = uniqueTerms
    .filter(isValidSearchTerm);


  // ----------------------------------------------------------
  // We expect exactly 4 good search terms because the AI
  // prompt explicitly requires exactly 4.
  // ----------------------------------------------------------

  if (validTerms.length < 2) {
    throw new Error(
      `Scene ${scene.scene} does not contain enough usable Pexels search terms.\n\n` +
      `AI returned:\n${JSON.stringify(aiScene.searchTerms)}`
    );
  }


  // ----------------------------------------------------------
  // Keep maximum 4 terms
  // ----------------------------------------------------------

  const finalTerms = validTerms.slice(0, 4);


  // ----------------------------------------------------------
  // Final scene object
  // ----------------------------------------------------------

  return {
    text: String(scene.description || '').trim(),

    searchTerms: finalTerms
  };

});


// ============================================================
// 10. FINAL SAFETY CHECK
// ============================================================

if (scenes.length !== 4) {
  throw new Error(
    `Final payload must contain exactly 4 scenes. Found ${scenes.length}.`
  );
}

scenes.forEach((scene, index) => {

  if (!Array.isArray(scene.searchTerms)) {
    throw new Error(
      `Final scene ${index + 1} does not have searchTerms.`
    );
  }

  if (scene.searchTerms.length < 2) {
    throw new Error(
      `Final scene ${index + 1} has fewer than 2 usable Pexels search terms.`
    );
  }

});


// ============================================================
// 11. BUILD FINAL SHORT VIDEO MAKER PAYLOAD
// ============================================================

return [
  {
    json: {

      // ------------------------------------------------------
      // Original video title
      // ------------------------------------------------------

      video_title: source.video_title,


      // ------------------------------------------------------
      // Original voiceover
      // ------------------------------------------------------

      final_voiceover: source.final_voiceover,


      // ------------------------------------------------------
      // Processed scenes
      // ------------------------------------------------------

      scenes: scenes,


      // ------------------------------------------------------
      // Short Video Maker configuration
      // ------------------------------------------------------

      config: {

        // Give the video 1.5 seconds of additional time
        // after the voiceover finishes.
        paddingBack: 1500,

        // Keep captions at the bottom.
        captionPosition: "bottom",

        // Voice used by Short Video Maker.
        voice: "af_heart",

        // Vertical video for TikTok / Reels / Shorts.
        orientation: "portrait",

        // IMPORTANT:
        // Background music is muted.
        musicVolume: "muted"

      }

    }
  }
];
